<?php require_once __DIR__ . '/../includes/functions.php'; if($_SERVER['REQUEST_METHOD']!=='POST')exit; verify_csrf(); $id=filter_input(INPUT_POST,'product_id',FILTER_VALIDATE_INT);$name=trim($_POST['customer_name']??'');$rating=filter_input(INPUT_POST,'rating',FILTER_VALIDATE_INT);$comment=trim($_POST['comment']??''); if(!$id||$name===''||!$rating||$rating<1||$rating>5||$comment===''){flash('error','Please complete every review field.');header('Location: ../product-details.php?id='.$id);exit;} $check=db()->prepare('SELECT COUNT(*) FROM reviews WHERE product_id=? AND customer_name=? AND comment=? AND created_at > DATE_SUB(NOW(), INTERVAL 1 DAY)');$check->execute([$id,$name,$comment]);if($check->fetchColumn()){flash('error','This review was already submitted.');}else{$s=db()->prepare('INSERT INTO reviews(product_id,customer_name,rating,comment,status) VALUES(?,?,?,?,"pending")');$s->execute([$id,$name,$rating,$comment]);flash('success','Thank you—your review is awaiting approval.');}header('Location: ../product-details.php?id='.$id);
